import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Self-hosted Overview","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/index.md","filePath":"self-hosted/index.md","lastUpdated":1788855895000}'),s={name:"self-hosted/index.md"};function h(d,e,l,n,i,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="self-hosted-overview" tabindex="-1">Self-hosted Overview <a class="header-anchor" href="#self-hosted-overview" aria-label="Permalink to &quot;Self-hosted Overview&quot;">​</a></h1><p>Memoh runs as a server stack; the Web UI and the Desktop app are clients for it. Pick the server option first, then decide how you want to access it.</p><table tabindex="0"><thead><tr><th>Use case</th><th>Choose</th><th>Why</th></tr></thead><tbody><tr><td>Try Memoh with nothing to install</td><td><a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a></td><td>Hosted service, same product, no server to run.</td></tr><tr><td>Shared server, remote access, public/private channels, production uptime, multi-user or multi-tenant usage</td><td><a href="/self-hosted/docker.html">Server Deploy</a></td><td>The Docker Compose stack keeps the backend, Web UI, PostgreSQL (with pgvector for memory), and workspace runtime online.</td></tr><tr><td>A native app on your own computer, optionally shared with bots as a Computer</td><td><a href="/self-hosted/desktop.html">Desktop</a></td><td>Native client that connects to Cloud or your server; it does not run a local server.</td></tr></tbody></table><h2 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h2><p>Use Server Deploy when Memoh should be reachable by multiple users, run continuously, or connect to external channels such as Telegram, Discord, Feishu, WeChat, WeChat Official Account, Email, and more.</p><p>Start with the <a href="/guides/quick-start.html">Quick Start</a> for the fastest route, then read <a href="/self-hosted/docker.html">Server Deploy</a> for the full reference.</p><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><p>Use Desktop when you want Memoh to behave like a native app with a tray icon and shortcuts, or when you want server-side bots to use your computer&#39;s files, shell, and browser. Desktop always connects to a server (Cloud or self-hosted); see <a href="/self-hosted/desktop.html">Desktop</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/self-hosted/workspace-backends.html">Workspace Backends</a> explains Docker, containerd, Apple, and local workspace runtime choices.</li><li><a href="/guides/computers.html">Computers</a> covers sharing your own machines with bots.</li></ul>',10)])])}const m=t(s,[["render",h]]);export{u as __pageData,m as default};
